"""
Model interface implementations.
"""

from typing import Any, Dict, Optional
import os

from .base import ModelInterface


class OpenAIModel(ModelInterface):
    """Interface for OpenAI API models."""

    def __init__(
        self,
        model_id: str = "gpt-4",
        api_key: Optional[str] = None,
        temperature: float = 0.0,
        max_tokens: int = 1024,
    ):
        self.model_id = model_id
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        self.temperature = temperature
        self.max_tokens = max_tokens
        self._client = None

    @property
    def client(self):
        """Lazy initialization of OpenAI client."""
        if self._client is None:
            try:
                from openai import OpenAI
                self._client = OpenAI(api_key=self.api_key)
            except ImportError:
                raise ImportError("openai package required. Install with: pip install openai")
        return self._client

    def generate(self, prompt: str, **kwargs) -> str:
        """Generate a response using the OpenAI API."""
        temperature = kwargs.get("temperature", self.temperature)
        max_tokens = kwargs.get("max_tokens", self.max_tokens)

        response = self.client.chat.completions.create(
            model=self.model_id,
            messages=[{"role": "user", "content": prompt}],
            temperature=temperature,
            max_tokens=max_tokens,
        )

        return response.choices[0].message.content

    def get_metadata(self) -> Dict[str, Any]:
        return {
            "provider": "openai",
            "model_id": self.model_id,
            "temperature": self.temperature,
            "max_tokens": self.max_tokens,
        }


class AnthropicModel(ModelInterface):
    """Interface for Anthropic API models."""

    def __init__(
        self,
        model_id: str = "claude-3-5-sonnet-20241022",
        api_key: Optional[str] = None,
        temperature: float = 0.0,
        max_tokens: int = 1024,
    ):
        self.model_id = model_id
        self.api_key = api_key or os.environ.get("ANTHROPIC_API_KEY")
        self.temperature = temperature
        self.max_tokens = max_tokens
        self._client = None

    @property
    def client(self):
        """Lazy initialization of Anthropic client."""
        if self._client is None:
            try:
                import anthropic
                self._client = anthropic.Anthropic(api_key=self.api_key)
            except ImportError:
                raise ImportError("anthropic package required. Install with: pip install anthropic")
        return self._client

    def generate(self, prompt: str, **kwargs) -> str:
        """Generate a response using the Anthropic API."""
        temperature = kwargs.get("temperature", self.temperature)
        max_tokens = kwargs.get("max_tokens", self.max_tokens)

        response = self.client.messages.create(
            model=self.model_id,
            max_tokens=max_tokens,
            temperature=temperature,
            messages=[{"role": "user", "content": prompt}],
        )

        return response.content[0].text

    def get_metadata(self) -> Dict[str, Any]:
        return {
            "provider": "anthropic",
            "model_id": self.model_id,
            "temperature": self.temperature,
            "max_tokens": self.max_tokens,
        }


class MockModel(ModelInterface):
    """Mock model for testing evaluations."""

    def __init__(self, responses: Optional[Dict[str, str]] = None):
        self.model_id = "mock-model"
        self.responses = responses or {}
        self.call_history = []

    def generate(self, prompt: str, **kwargs) -> str:
        """Return mock response or echo prompt."""
        self.call_history.append({"prompt": prompt, "kwargs": kwargs})

        # Check for exact match
        if prompt in self.responses:
            return self.responses[prompt]

        # Check for partial match
        for key, value in self.responses.items():
            if key in prompt:
                return value

        # Default: echo
        return f"[MOCK RESPONSE TO: {prompt[:50]}...]"

    def get_metadata(self) -> Dict[str, Any]:
        return {
            "provider": "mock",
            "model_id": self.model_id,
            "num_canned_responses": len(self.responses),
        }
